contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 initialDifficulty) public {
        // Set a known initial difficulty so we can observe it is unchanged.
        c.AdjustDifficulty(initialDifficulty); if (__ESBMC_reverted()) return;
        uint256 diffBefore = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 limitBefore = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.AdjustBetAmounts(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 limitAfter = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 diffAfter = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        assert(reverted ? (limitAfter == limitBefore && diffAfter == diffBefore)
                        : (limitAfter == amount && diffAfter == diffBefore));
    }

    receive() external payable {}
}

