import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount, uint256 initialDifficulty) internal {
        try c.AdjustDifficulty(initialDifficulty) {} catch { return; }
        uint256 diffBefore;
        try c.currentDifficulty() returns (uint256 __r) { diffBefore = __r; } catch { return; }
        uint256 limitBefore;
        try c.currentBetLimit() returns (uint256 __r) { limitBefore = __r; } catch { return; }
        bool reverted;
        try c.AdjustBetAmounts(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 limitAfter;
        try c.currentBetLimit() returns (uint256 __r) { limitAfter = __r; } catch { return; }
        uint256 diffAfter;
        try c.currentDifficulty() returns (uint256 __r) { diffAfter = __r; } catch { return; }
        assertTrue(reverted ? (limitAfter == limitBefore && diffAfter == diffBefore)
                        : (limitAfter == amount && diffAfter == diffBefore));
    }

    function testFuzz_run(uint256 amount, uint256 initialDifficulty) public {
        _run(amount, initialDifficulty);
    }

    receive() external payable {}
}
